package com.example.onlineshop.catalog.api;
import org.springframework.boot.actuate.health.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Component;
@Component("catalogReconciliation") final class CatalogReconciliationHealthIndicator implements HealthIndicator {private final JdbcTemplate jdbc;CatalogReconciliationHealthIndicator(JdbcTemplate jdbc){this.jdbc=jdbc;}public Health health(){try{var statuses=jdbc.query("SELECT status FROM catalog_legacy_reconciliation WHERE id=1",(r,n)->r.getString(1));String status=statuses.isEmpty()?"MISSING":statuses.get(0);return "READY".equals(status)?Health.up().withDetail("status",status).build():Health.down().withDetail("status",status).build();}catch(RuntimeException e){return Health.down().withDetail("status","UNAVAILABLE").build();}}}
